DROP TABLE IF EXISTS `dir_data`;
CREATE TABLE `dir_data` (
  `id` mediumint(11) unsigned NOT NULL AUTO_INCREMENT,
  `tag` smallint(5) unsigned NOT NULL DEFAULT '1',
  `name` varchar(255) DEFAULT NULL,
  `tablename` varchar(64) DEFAULT NULL,
  `type` int(11) unsigned NOT NULL DEFAULT '0',
  `template` varchar(250) DEFAULT NULL,
  `typ` int(11) NOT NULL DEFAULT '0',
  `dat` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `preview` varchar(32) DEFAULT NULL,
  `hidden` tinyint(3) unsigned NOT NULL DEFAULT '0',
  `is_server` tinyint(3) unsigned NOT NULL DEFAULT '0',
  `templateDir` varchar(100) DEFAULT NULL,
  `inheritFields` tinyint(3) unsigned NOT NULL DEFAULT '1',
  `pic` varchar(1024) DEFAULT NULL,
  `meta_title` varchar(1000) DEFAULT NULL,
  `meta_keywords` varchar(1000) DEFAULT NULL,
  `meta_description` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
);


TRUNCATE TABLE `dir_structure`;

TRUNCATE TABLE `gallery_picture`;

DROP TABLE IF EXISTS `materials`;
CREATE TABLE `materials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `idcat` int(11) DEFAULT NULL,
  `dat` datetime DEFAULT NULL,
  `dat_update` datetime DEFAULT NULL,
  `name` varchar(2048) DEFAULT NULL,
  `type` int(11) DEFAULT NULL,
  `autor` int(11) NOT NULL DEFAULT '0',
  `tag` int(11) NOT NULL DEFAULT '1',
  `alias` varchar(255) NOT NULL,
  `text` text,
  `short` varchar(1000) DEFAULT NULL,
  `pic` varchar(1024) DEFAULT NULL,
  `meta_title` varchar(1000) DEFAULT NULL,
  `meta_keywords` varchar(1000) DEFAULT NULL,
  `meta_description` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idcat` (`idcat`),
  KEY `dat` (`dat`),
  KEY `alias` (`alias`)
);


TRUNCATE TABLE `menus`;

TRUNCATE TABLE `sale_person_type`;

TRUNCATE TABLE `sale_delivery`;

TRUNCATE TABLE `sale_delivery_payment`;

TRUNCATE TABLE `sale_filter`;

TRUNCATE TABLE `sale_order_props`;

TRUNCATE TABLE `sale_payment`;

TRUNCATE TABLE `sale_payment_person_type`;

DROP TABLE IF EXISTS `sale_products`;
CREATE TABLE IF NOT EXISTS `sale_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `idcat` int(11) DEFAULT NULL,
  `dat` datetime DEFAULT NULL,
  `dat_update` datetime DEFAULT NULL,
  `name` varchar(300) DEFAULT NULL,
  `type` int(11) DEFAULT NULL,
  `autor` int(11) DEFAULT NULL,
  `tag` int(11) NOT NULL DEFAULT '1',
  `alias` varchar(255) NOT NULL,
  `pic` varchar(1024) DEFAULT NULL,
  `short` varchar(1000) DEFAULT NULL,
  `price` double DEFAULT NULL,
  `text` longtext,
  `hot` tinyint(4) DEFAULT '0',
  `code` varchar(100) DEFAULT NULL,
  `brand` int(11) DEFAULT NULL,
  `meta_title` varchar(1000) DEFAULT NULL,
  `meta_keywords` varchar(1000) DEFAULT NULL,
  `meta_description` varchar(1000) DEFAULT NULL,
  `patron` enum('быстрозажимной','ключевой','квадрат 1"','квадрат 3/4"','квадрат 1/2"','под биты','SDS+','SDS-max') DEFAULT NULL,
  `power` int(11) DEFAULT NULL,
  `new` tinyint(4) DEFAULT '0',
  `stal` varchar(50) DEFAULT NULL,
  `diapazon_zazhima_sverlilnogo_patrona` varchar(50) DEFAULT NULL,
  `napryazhenie_akkumulyatornogo_bloka` varchar(50) DEFAULT NULL,
  `ves_s_akkumulyatornym_blokom` varchar(50) DEFAULT NULL,
  `vid_akkumulyatornogo_bloka` varchar(50) DEFAULT NULL,
  `maks_myagkij_vrashhayushhij_moment` varchar(50) DEFAULT NULL,
  `maks_zhestkij_vrashhayushhij_moment` varchar(50) DEFAULT NULL,
  `reguliruemyj_krutyashhij_moment` varchar(50) DEFAULT NULL,
  `derevo` varchar(50) DEFAULT NULL,
  `znacheniya_dlya_chisla_oborotov_kholostogo_khoda` varchar(50) DEFAULT NULL,
  `komplektatsiya` varchar(1000) DEFAULT NULL,
  `nominalnaya_potreblyaemaya_moshhnost` varchar(50) DEFAULT NULL,
  `dlina_kabelya` varchar(50) DEFAULT NULL,
  `otdavaemaya_moshhnost` varchar(50) DEFAULT NULL,
  `chislo_oborotov_kholostogo_khoda` varchar(50) DEFAULT NULL,
  `diametr_shejki_zazhima` varchar(50) DEFAULT NULL,
  `maks_chislo_taktov` varchar(50) DEFAULT NULL,
  `maks_ehnergiya_odnogo_udara_epta` varchar(50) DEFAULT NULL,
  `moshhnost_udara` varchar(50) DEFAULT NULL,
  `ves_bez_setevogo_kabelya` varchar(50) DEFAULT NULL,
  `krutyashhij_moment` varchar(50) DEFAULT NULL,
  `beton_s_udarnymi_sverlami` varchar(50) DEFAULT NULL,
  `beton_s_frezernymi_koronkami` double DEFAULT NULL,
  `beton_s_polymi_koronkami` double DEFAULT NULL,
  `chislo_oborotov_pri_nominalnoj_nagruzke` varchar(50) DEFAULT NULL,
  `myagkoe_derevo` varchar(50) DEFAULT NULL,
  `maks_krutyashhij_moment` varchar(50) DEFAULT NULL,
  `sverlilnyj_shpindel_s_vnutrennim_shestigrannikom` varchar(50) DEFAULT NULL,
  `emkost_akkumulyatornogo_bloka` varchar(50) DEFAULT NULL,
  `diapazon_naklona` varchar(50) DEFAULT NULL,
  `chastota_khoda_na_kholostykh_oborotakh` varchar(50) DEFAULT NULL,
  `tsvetnye_metally` varchar(50) DEFAULT NULL,
  `stalnoj_list` varchar(50) DEFAULT NULL,
  `stupeni_mayatnikovogo_khoda` varchar(50) DEFAULT NULL,
  `quantity` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idcat` (`idcat`),
  KEY `dat` (`dat`),
  KEY `alias` (`alias`)
);


DROP TABLE IF EXISTS `sale_products_gallery_picture_pictures`;
CREATE TABLE `sale_products_gallery_picture_pictures` (
  `id` int(11) NOT NULL,
  `dest` int(11) NOT NULL,
  `tag` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`,`dest`),
  KEY `dest` (`dest`)
);

